function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function sla(level){
  level=String(level||'P1');
  if(level.indexOf('P0')>=0) return {respond:5, mitigate:30, desc:'全面事故，最高优先级处理'};
  if(level.indexOf('P2')>=0) return {respond:60, mitigate:1440, desc:'一般故障，工作时间内处理'};
  return {respond:15, mitigate:120, desc:'重要故障，需尽快恢复服务'};
}
function buildRunbook(o){
  o=o||{};
  var service=String(o.service||'').trim()||'（待填写服务名）';
  var level=String(o.level||'P1');
  var scenes=splitLines(o.scenes);
  if(!scenes.length) scenes=['服务 5xx 错误率升高','核心接口响应延迟异常'];
  var contact=String(o.contact||'').trim()||'值班电话 / 企业微信群';
  var s=sla(level);
  var steps=['确认告警真实性并截图留痕','查看监控大盘与最近变更（发布 / 配置 / 依赖）','评估影响面（用户量与核心链路）','按场景处置手册执行缓解','通报进展并记录时间线','恢复后 48 小时内完成复盘'];
  var lines=[];
  lines.push('# Runbook：'+service+'（'+level+'）');
  lines.push('');
  lines.push('## 一、响应目标（SLA）');
  lines.push('- 响应时限：'+s.respond+' 分钟内确认告警');
  lines.push('- 缓解时限：'+s.mitigate+' 分钟内恢复或降级');
  lines.push('- 级别说明：'+s.desc);
  lines.push('');
  lines.push('## 二、响应流程');
  steps.forEach(function(st,i){ lines.push((i+1)+'. '+st); });
  lines.push('');
  lines.push('## 三、场景处置手册');
  scenes.forEach(function(sc,i){
    lines.push('### 场景 '+(i+1)+'：'+sc);
    lines.push('- 排查：查看相关日志与指标（错误率 / 延迟 / QPS）');
    lines.push('- 处置：优先回滚最近变更，其次降级或扩容');
    lines.push('- 验证：核心接口探活通过后持续观察 15 分钟');
    lines.push('');
  });
  lines.push('## 四、升级路径');
  lines.push('- 一线值班 → '+contact);
  lines.push('- 超时未缓解：升级至服务负责人与二线 on-call');
  lines.push('');
  lines.push('## 五、复盘要求');
  lines.push('- 输出时间线 / 根因 / 行动项（负责人 + 截止日期）');
  return {title:service+' Runbook', level:level, respondMinutes:s.respond,
          mitigateMinutes:s.mitigate, sceneCount:scenes.length, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, sla:sla, buildRunbook:buildRunbook};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RunbookForgePure = EXPORTS; }
